B.bbh=new A.l_("\u0627\u0634\u0631\u0627\u0642","\u0646\u0645\u0627\u0632 \u0627\u0634\u0631\u0627\u0642","\u0646\u0645\u0627\u0632 \u0645\u0633\u062a\u062d\u0628 \u067e\u0633 \u0627\u0632 \u0637\u0644\u0648\u0639 \u0622\u0641\u062a\u0627\u0628\u060c \u0647\u0646\u06af\u0627\u0645\u06cc \u06a9\u0647 \u062e\u0648\u0631\u0634\u06cc\u062f \u0628\u0647 \u0627\u0646\u062f\u0627\u0632\u0647\u0654 \u06cc\u06a9 \u0646\u06cc\u0632\u0647 \u0628\u0627\u0644\u0627 \u0622\u0645\u062f\u0647 \u0628\u0627\u0634\u062f. \u06a9\u0633\u06cc \u06a9\u0647 \u067e\u0633 \u0627\u0632 \u0646\u0645\u0627\u0632 \u0635\u0628\u062d \u0628\u0631 \u0645\u0635\u0644\u0627\u06cc \u062e\u0648\u062f \u0628\u0647 \u0630\u06a9\u0631 \u0628\u0646\u0634\u06cc\u0646\u062f \u062a\u0627 \u0622\u0641\u062a\u0627\u0628 \u0628\u0631\u0622\u06cc\u062f \u0648 \u0633\u067e\u0633 \u0627\u06cc\u0646 \u0646\u0645\u0627\u0632 \u0631\u0627 \u0628\u062e\u0648\u0627\u0646\u062f\u060c \u0627\u062c\u0631\u06cc \u0628\u0632\u0631\u06af \u062f\u0627\u0631\u062f.","\u062d\u062f\u0648\u062f \u06f1\u06f5 \u062a\u0627 \u06f2\u06f0 \u062f\u0642\u06cc\u0642\u0647 \u067e\u0633 \u0627\u0632 \u0637\u0644\u0648\u0639 \u0622\u0641\u062a\u0627\u0628 (\u067e\u0627\u06cc\u0627\u0646 \u0648\u0642\u062a \u06a9\u0631\u0627\u0647\u062a) \u062a\u0627 \u067e\u06cc\u0634 \u0627\u0632 \u0622\u063a\u0627\u0632 \u0648\u0642\u062a \u0686\u0627\u0634\u062a.","\u06f2 \u0631\u06a9\u0639\u062a (\u062a\u0627 \u06f4 \u0631\u06a9\u0639\u062a)",B.ajw,B.ant,B.alX,null)
